import{GameState}from'../game/state.js';import{CanvasRenderer}from'../renderer/canvas-renderer.js';import{GestureController}from'../input/gesture.js';import{AudioSystem}from'../audio/audio.js';import{UI}from'../ui/ui.js';import{save}from'../persistence/save.js';import{selfTest}from'../tests/selftest.js';
const canvas=document.querySelector('#game'),game=new GameState(),renderer=new CanvasRenderer(canvas),audio=new AudioSystem(),ui=new UI();let wasLoot=false,wasComplete=false,last=performance.now();
const gesture=new GestureController(canvas,{onPreview:(dx,dy,dir)=>renderer.setPreview(dx,dy,dir),onSwipe:dir=>{if(game.mode!=='play')return;audio.unlock();game.shift(dir);renderer.gravityPulse();audio.shift()}});
function start(){audio.unlock();game.start();wasLoot=false;wasComplete=false;ui.showPlay()}document.querySelector('#play').addEventListener('click',start);document.querySelector('#retry').addEventListener('click',start);
function frame(now){const dt=Math.min(.033,(now-last)/1000);last=now;if(game.mode==='play'){game.update(dt);ui.update(game);if(game.hasLoot&&!wasLoot){wasLoot=true;audio.loot();renderer.gravityPulse()}if(game.complete&&!wasComplete){wasComplete=true;const score=game.score();save.record(score);audio.success();ui.showResult(score,game.elapsed,game.shifts)}}renderer.render(game,dt);requestAnimationFrame(frame)}
selfTest();requestAnimationFrame(frame);document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.visibilityState==='visible')audio.ctx?.resume?.()});if('serviceWorker'in navigator&&location.protocol.startsWith('http'))addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('SW',e)));